using System;
using System.Linq;
using System.Collections.Generic;
public class Solution {
    public int LongestPath(int[][] matrix) {
        int rows = matrix.Length, cols = matrix[0].Length; var degree = new int[rows, cols];
        var queue = new System.Collections.Generic.Queue<(int r, int c)>();
        var directions = new[] { (-1, 0), (1, 0), (0, -1), (0, 1) };
        bool Inside(int r, int c) => r >= 0 && c >= 0 && r < rows && c < cols;
        for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) {
            foreach (var (dr, dc) in directions) if (Inside(r + dr, c + dc) && matrix[r + dr][c + dc] < matrix[r][c]) degree[r, c]++;
            if (degree[r, c] == 0) queue.Enqueue((r, c));
        }
        int layers = 0;
        while (queue.Count > 0) {
            int count = queue.Count; layers++;
            while (count-- > 0) {
                var (r, c) = queue.Dequeue();
                foreach (var (dr, dc) in directions) {
                    int nr = r + dr, nc = c + dc;
                    if (Inside(nr, nc) && matrix[nr][nc] > matrix[r][c] && --degree[nr, nc] == 0) queue.Enqueue((nr, nc));
                }
            }
        }
        return layers;
    }
}

ch8-08.javascript:
function LongestPath(m) {
  const R = m.length, C = m[0].length, dp = Array(R * C).fill(0)
  function larger(k) {
    const r = Math.floor(k / C), c = k % C
    return [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]]
      .filter(([i, j]) => i >= 0 && j >= 0 && i < R && j < C && m[i][j] > m[r][c]).map(([i, j]) => i * C + j)
  }
  for (let start = 0; start < dp.length; start++) {
    const stack = [start]
    while (stack.length) {
      const mark = stack.pop(), k = mark < 0 ? -mark - 1 : mark
      if (dp[k]) continue
      const next = larger(k)
      if (mark < 0) dp[k] = 1 + Math.max(0, ...next.map(i => dp[i]))
      else { stack.push(-k - 1); for (const i of next) if (!dp[i]) stack.push(i) }
    }
  }
  return Math.max(...dp)
}

